void DecodeEngine::finish_moe_exchange() {
  if (!moe_pending_) return;
  const int H = cfg_.hidden_size;
  ep_->exchange_end(&stages_.fabric);
  moe_pending_ = false;
  auto* stage = static_cast<bf16*>(ep_->stage());
