          gemv_nvfp4(moe_gu_ + static_cast<std::size_t>(crow) * (2 * MI) + MI, e.up_packed,
                     e.up_scale, 1.0f, moe_x_ + static_cast<std::size_t>(crow) * H, MI, H,
