  // and not merely enqueued.
  cuda_check(cudaStreamSynchronize(stream_), "sync before RDMA write");
  ep_->exchange_begin(send_off, own_n);
  moe_pending_ = true;
  moe_recv_off_rows_ = recv_off;
  moe_recv_n_ = rows - own_n;
  moe_rows_ = rows;
  moe_batch_ = batch;
  return true;
}

