    __syncthreads();
    if (threadIdx.x == 0) {
      int left = remaining;
      int bucket = 255;
      for (; bucket >= 0; --bucket) {
        if (static_cast<int>(hist[bucket]) >= left) break;
        left -= static_cast<int>(hist[bucket]);
