  __syncthreads();
  for (int i = threadIdx.x; i < n_p; i += blockDim.x) {
    if (order_key(row[i]) == prefix_hi) {
      const int slot = atomicAdd(&count, 1);
      if (slot < select_k) sel_row[slot] = i;
    }
