  cudaMemcpy(h.data(), ctx, h.size() * sizeof(float), cudaMemcpyDeviceToHost);
  cudaStreamSynchronize(stream_);
  for (int m = 0; m < batch; ++m) {
    double s = 0.0, amax = 0.0;
    for (int hd = 0; hd < heads; ++hd) {
