// path's writes.
void DecodeEngine::mla_dump_ints(const char* tag, int layer, const int* sel, const int* n_tok,
                                 int stride, int batch) {
  static bool on = std::getenv("ROCKET_LHC_CHECKSUM") != nullptr;
  if (!on) return;
