  __shared__ int si[256 * 16];
  float lv[16]; int li[16];
  for (int j = 0; j < 16; ++j) { lv[j] = -INFINITY; li[j] = -1; }
  for (int v = threadIdx.x; v < vocab; v += blockDim.x) {
    const float x = logits[static_cast<long long>(r) * vocab + v];
