  __syncthreads();
  for (int step = 0; step < draft; ++step) {
    const int row = req * draft + step;
    const int predecessor = step == 0 ? anchor[req] : candidates[(row - 1) * 16 + previous];
    const int candidate = candidates[row * 16 + lane];
