    for (int d = 0; d < rank; ++d)
      edge += f(pred[static_cast<long long>(predecessor) * rank + d]) *
              f(projected[static_cast<long long>(row) * rank + d]) *
              f(succ[static_cast<long long>(candidate) * rank + d]);
